/**
 * pyerrors.mjs — Python exception shapes reproduced in JavaScript.
 *
 * The migrated program has to distinguish three distinct exit behaviours that
 * CPython gives us for free:
 *
 *   * `SystemExit`          -> argparse's `--help` (code 0) and `error()` (code 2)
 *   * `UnicodeEncodeError`  -> `str.encode('utf-8')` over lone surrogates (code 1,
 *                              after a traceback on stderr)
 *   * `ValueError`/`TypeError` -> library misuse, surfaced with a traceback
 *
 * Each class carries the exact `__str__` rendering CPython produces, because the
 * text ends up on stderr verbatim.
 */

/** Base class so callers can test `err instanceof PyError`. */
export class PyError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PyError';
  }

  /** Fully-qualified name used on the last line of a traceback. */
  get pyName() {
    return this.name;
  }

  /** CPython's `str(exc)` — the text after the `ClassName: ` prefix. */
  toPyString() {
    return this.message;
  }
}

/** `raise SystemExit(code)`, which is what `sys.exit()` and `parser.error()` do. */
export class SystemExit extends PyError {
  constructor(code = 0) {
    super(String(code));
    this.name = 'SystemExit';
    this.code = code;
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

export class PyTypeError extends PyError {
  constructor(message) {
    super(message);
    this.name = 'TypeError';
  }
}

/**
 * Renders a single code point the way CPython's `unicode_repr`-style helper does
 * inside `UnicodeEncodeError.__str__`: `\xXX`, `\uXXXX` or `\UXXXXXXXX`,
 * always lowercase hex.
 */
function escapeCodePoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * `UnicodeEncodeError(encoding, object, start, end, reason)`.
 *
 * CPython formats the message two different ways depending on how many code
 * points are unencodable:
 *
 *   end == start + 1:
 *     'utf-8' codec can't encode character '\udc80' in position 5: surrogates not allowed
 *   otherwise:
 *     'utf-8' codec can't encode characters in position 2-3: surrogates not allowed
 *
 * `start`/`end` are indices into the *code point* sequence of `object`, not
 * UTF-16 units — see `pyunicode.mjs`.
 */
export class UnicodeEncodeError extends PyError {
  constructor(encoding, object, start, end, reason) {
    let message;
    if (end === start + 1) {
      const cp = codePointAtIndex(object, start);
      message =
        `'${encoding}' codec can't encode character '${escapeCodePoint(cp)}' ` +
        `in position ${start}: ${reason}`;
    } else {
      message =
        `'${encoding}' codec can't encode characters ` +
        `in position ${start}-${end - 1}: ${reason}`;
    }
    super(message);
    this.name = 'UnicodeEncodeError';
    this.encoding = encoding;
    this.object = object;
    this.start = start;
    this.end = end;
    this.reason = reason;
  }
}

/** Code point at a *code point* index (not a UTF-16 index). */
function codePointAtIndex(str, index) {
  let i = 0;
  for (const ch of str) {
    if (i === index) return ch.codePointAt(0);
    i += 1;
  }
  return 0xfffd;
}

