/**
 * pybytes.mjs — a `bytes` value plus CPython's `repr()` for it.
 *
 * `encode_canonical_json` returns `bytes`, and `print()` of a `bytes` object
 * emits its repr. Getting that repr byte-exact is most of the observable output
 * of this program, so the rules are spelled out below.
 */

/**
 * CPython's `bytes_repr`:
 *
 *   * The quote character is `'`, unless the value contains `'` and no `"`, in
 *     which case `"` is used instead.
 *   * `\\` for a backslash, and `\` + quote for the active quote character. The
 *     *inactive* quote character is emitted raw.
 *   * `\t`, `\n`, `\r` for 0x09, 0x0a, 0x0d.
 *   * `\xNN` (lowercase hex) for any other byte below 0x20 or at/above 0x7f.
 *   * Everything else is emitted as its ASCII character.
 */
export function bytesRepr(bytes) {
  const buf = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);

  let hasSingle = false;
  let hasDouble = false;
  for (const b of buf) {
    if (b === 0x27) hasSingle = true;
    else if (b === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quoteChar = String.fromCharCode(quote);

  let body = '';
  for (const b of buf) {
    if (b === quote || b === 0x5c) {
      body += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      body += '\\t';
    } else if (b === 0x0a) {
      body += '\\n';
    } else if (b === 0x0d) {
      body += '\\r';
    } else if (b < 0x20 || b >= 0x7f) {
      body += '\\x' + b.toString(16).padStart(2, '0');
    } else {
      body += String.fromCharCode(b);
    }
  }

  return 'b' + quoteChar + body + quoteChar;
}

/**
 * Thin `bytes` wrapper. It exists so `pyPrint` can tell a `bytes` result apart
 * from a `str` without guessing, mirroring how the Python source relies on
 * `print(b'...')` dispatching to `bytes.__repr__`.
 */
export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
  }

  static from(bytes) {
    return new PyBytes(bytes);
  }

  /** `len(b)` */
  get length() {
    return this.bytes.length;
  }

  /** `repr(b)` */
  repr() {
    return bytesRepr(this.bytes);
  }

  toString() {
    return this.repr();
  }
}

