/**
 * pyio.mjs — `print()` and stderr writes with CPython's flushing guarantees.
 *
 * `process.stdout.write` is asynchronous when stdout is a pipe, so a subsequent
 * `process.exit()` can truncate output. Everything here goes through
 * `fs.writeSync` instead, which keeps stdout/stderr ordering intact and makes
 * the write complete before an exit path runs.
 */

import { writeSync } from 'node:fs';
import { PyBytes, bytesRepr } from './pybytes.mjs';
import { pyFloatRepr, pyIntRepr, PyFloat } from './pynumber.mjs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

function writeAllSync(fd, text) {
  const buffer = Buffer.from(text, 'utf8');
  let offset = 0;
  while (offset < buffer.length) {
    try {
      offset += writeSync(fd, buffer, offset);
    } catch (err) {
      if (err.code === 'EAGAIN') continue; // non-blocking fd: retry
      if (err.code === 'EPIPE') return; // reader went away
      throw err;
    }
  }
}

export function writeStdout(text) {
  writeAllSync(STDOUT_FD, text);
}

export function writeStderr(text) {
  writeAllSync(STDERR_FD, text);
}

/** `repr()` for the values this program can print. */
export function pyRepr(value) {
  if (value instanceof PyBytes) return value.repr();
  if (value instanceof Uint8Array) return bytesRepr(value);
  if (value === null || value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (value instanceof PyFloat) return pyFloatRepr(value.value);
  if (typeof value === 'bigint') return pyIntRepr(value);
  if (typeof value === 'number') {
    return Number.isInteger(value) ? pyIntRepr(value) : pyFloatRepr(value);
  }
  if (Array.isArray(value)) return '[' + value.map(pyRepr).join(', ') + ']';
  return String(value);
}

/**
 * `print(*values, sep=' ', end='\n')`.
 *
 * `print` renders each argument with `str()`, which for `bytes` is its `repr()`
 * — that is exactly what `print(result1)` relies on in the Python source.
 */
export function pyPrint(...values) {
  const rendered = values.map((value) => (typeof value === 'string' ? value : pyRepr(value)));
  writeStdout(rendered.join(' ') + '\n');
}

