/**
 * textwrap.mjs — the slice of `textwrap.wrap` that argparse's HelpFormatter
 * needs: collapse whitespace, then greedily fill lines, breaking a word only
 * when it cannot fit on a line by itself.
 */

/** `argparse.HelpFormatter._whitespace_matcher.sub(' ', text).strip()` */
export function collapseWhitespace(text) {
  return text.replace(/[\t\n\x0b\f\r ]+/g, ' ').replace(/^ +| +$/g, '');
}

/**
 * `textwrap.wrap(text, width)` with argparse's defaults. Returns a list of
 * lines; an all-whitespace input yields an empty list, as in Python.
 */
export function wrapText(text, width) {
  const normalized = collapseWhitespace(text);
  if (normalized === '') return [];
  const limit = Math.max(1, width);

  const lines = [];
  let current = '';

  for (let word of normalized.split(' ')) {
    if (word === '') continue;

    if (current === '') {
      // A word longer than the whole line gets chopped (break_long_words=True).
      while (word.length > limit) {
        lines.push(word.slice(0, limit));
        word = word.slice(limit);
      }
      current = word;
      continue;
    }

    if (current.length + 1 + word.length <= limit) {
      current += ' ' + word;
      continue;
    }

    lines.push(current);
    current = '';
    while (word.length > limit) {
      lines.push(word.slice(0, limit));
      word = word.slice(limit);
    }
    current = word;
  }

  if (current !== '') lines.push(current);
  return lines;
}

/** `textwrap.fill(text, width)` */
export function fillText(text, width, indent = '') {
  return wrapText(text, width - indent.length)
    .map((line) => indent + line)
    .join('\n');
}

