/**
 * pyargv.mjs — recovers `sys.argv` with Python's byte-level fidelity.
 *
 * CPython decodes argv as UTF-8 with `errors='surrogateescape'`, so an argument
 * containing invalid UTF-8 survives as lone surrogates and later makes
 * `encode_canonical_json` raise `UnicodeEncodeError`. Node instead decodes argv
 * lossily: invalid bytes are already U+FFFD by the time `process.argv` exists,
 * which would silently succeed where Python fails.
 *
 *   /workspace/dataset/test7_executable --a $'bad\x80byte' --b x
 *     -> UnicodeEncodeError: ... '\udc80' in position 5 ...   (exit 1)
 *
 * Reading `/proc/self/cmdline` gets the original bytes back, so the
 * surrogateescape decode can be performed properly. The result is cross-checked
 * against `process.argv` and the whole mechanism falls back to `process.argv`
 * whenever the platform does not cooperate — for valid UTF-8 input, which is
 * every realistic invocation, both paths agree exactly.
 */

import { readFileSync } from 'node:fs';
import { decodeSurrogateEscape } from './pyunicode.mjs';

/** Split a NUL-delimited `/proc/self/cmdline` payload into byte slices. */
function splitCmdline(buffer) {
  let bytes = buffer;
  // The payload ends with a trailing NUL terminator; drop exactly one so that a
  // genuinely empty final argument is still preserved.
  if (bytes.length > 0 && bytes[bytes.length - 1] === 0) {
    bytes = bytes.subarray(0, bytes.length - 1);
  }
  if (bytes.length === 0) return [];

  const parts = [];
  let start = 0;
  for (let i = 0; i < bytes.length; i += 1) {
    if (bytes[i] === 0) {
      parts.push(bytes.subarray(start, i));
      start = i + 1;
    }
  }
  parts.push(bytes.subarray(start));
  return parts;
}

/**
 * `sys.argv[1:]` — the script's own arguments as Python would see them.
 */
export function scriptArgs() {
  const fallback = process.argv.slice(2);
  if (fallback.length === 0) return fallback;

  try {
    const parts = splitCmdline(readFileSync('/proc/self/cmdline'));
    if (parts.length < fallback.length) return fallback;

    // The interpreter path and any node options come first; the script's own
    // arguments are always the trailing entries.
    const decoded = parts
      .slice(parts.length - fallback.length)
      .map((slice) => decodeSurrogateEscape(slice));

    // Guard against a misaligned tail: any entry Node decoded without loss must
    // match, otherwise distrust the raw bytes entirely.
    for (let i = 0; i < fallback.length; i += 1) {
      if (!fallback[i].includes('�') && decoded[i] !== fallback[i]) return fallback;
    }
    return decoded;
  } catch {
    return fallback;
  }
}

