    return new HelpFormatter(this.prog, this.formatterWidth).formatUsage(this.actions);
  }

  formatHelp() {
    const formatter = new HelpFormatter(this.prog, this.formatterWidth);
    return `${formatter.formatUsage(this.actions)}\n${formatter.formatOptionsSection(this.actions)}`;
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** `parser.error(message)` — usage on stderr, then `sys.exit(2)`. */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

