   * `_parse_optional`. Returns `null` when the string is a positional, or
   * `[action, optionString, explicitArg]` where `action` is `null` for an
   * option-looking string that matches nothing.
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!this.prefixChars.includes(argString[0])) return null;

    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) return null; // a bare "-" is a positional

    const equalsAt = argString.indexOf('=');
    if (equalsAt !== -1) {
      const optionString = argString.slice(0, equalsAt);
      const explicitArg = argString.slice(equalsAt + 1);
      if (this.optionStringActions.has(optionString)) {
        return [this.optionStringActions.get(optionString), optionString, explicitArg];
      }
    }

    const tuples = this.getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (tuples.length === 1) {
      return tuples[0];
    }

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) return null;
    if (argString.includes(' ')) return null;

    return [null, argString, null];
  }

  /** `_get_option_tuples` — prefix matching for long and short options. */
  getOptionTuples(optionString) {
    const chars = this.prefixChars;
    const result = [];

    if (chars.includes(optionString[0]) && chars.includes(optionString[1])) {
      if (!this.allowAbbrev) return result;
      const equalsAt = optionString.indexOf('=');
      const prefix = equalsAt !== -1 ? optionString.slice(0, equalsAt) : optionString;
      const explicitArg = equalsAt !== -1 ? optionString.slice(equalsAt + 1) : null;
      for (const [candidate, action] of this.optionStringActions) {
        if (candidate.startsWith(prefix)) result.push([action, candidate, explicitArg]);
      }
      return result;
    }

    const shortPrefix = optionString.slice(0, 2);
    const shortExplicitArg = optionString.slice(2);
    for (const [candidate, action] of this.optionStringActions) {
      if (candidate === shortPrefix) {
        result.push([action, candidate, shortExplicitArg]);
      } else if (candidate.startsWith(optionString)) {
        result.push([action, candidate, null]);
      }
    }
    return result;
