  /**
   * `_match_argument` for `nargs=None`. For optionals argparse strips `-` from
   * the nargs pattern, leaving `(A)`: the very next slot must be a plain value,
   * so a following option string or `--` is a hard error.
   */
  matchArgument(action, pattern) {
    if (action.nargs === 0) return 0;
    if (pattern.length >= 1 && pattern[0] === 'A') return 1;
    throw new ArgumentError(action, 'expected one argument');
  }

  /** `parse_args` */
  parseArgs(args) {
    const [namespace, extras] = this.parseKnownArgs(args);
    if (extras.length > 0) {
