  /** `parse_known_args` / `_parse_known_args` */
  parseKnownArgs(argStrings) {
    const args = Array.from(argStrings);
    const namespace = new Namespace();
    for (const action of this.actions) {
      if (action.action === 'store') namespace[action.dest] = action.defaultValue;
    }

    // Classify each argument: 'O' option, 'A' value, '-' the "--" separator.
    const pattern = [];
    const optionIndices = new Map();
    let sawSeparator = false;
    for (let i = 0; i < args.length; i += 1) {
      if (sawSeparator) {
        pattern.push('A');
        continue;
      }
      if (args[i] === '--') {
        pattern.push('-');
        sawSeparator = true;
        continue;
      }
      const optionTuple = this.parseOptional(args[i]);
      if (optionTuple === null) {
        pattern.push('A');
      } else {
        optionIndices.set(i, optionTuple);
        pattern.push('O');
      }
    }

    const seenActions = new Set();
    const extras = [];

    const takeAction = (action, values) => {
      seenActions.add(action);
      if (action.action === 'help') {
        this.printHelp();
        throw new SystemExit(0);
      }
      // type=str is the identity conversion.
      namespace[action.dest] = action.nargs === 0 ? true : values[0];
    };

    const consumeOptional = (startIndex) => {
      const [action, optionString, explicitArg] = optionIndices.get(startIndex);

      if (action === null) {
        extras.push(args[startIndex]);
        return startIndex + 1;
      }

      if (explicitArg !== null) {
        const argCount = this.matchArgument(action, ['A']);
        if (argCount === 1) {
          takeAction(action, [explicitArg]);
          return startIndex + 1;
        }
        // `--help=x`: a flag was handed a value it cannot use.
        throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
      }

      const start = startIndex + 1;
      const argCount = this.matchArgument(action, pattern.slice(start));
      const stop = start + argCount;
      takeAction(action, args.slice(start, stop));
      return stop;
    };

    const optionKeys = Array.from(optionIndices.keys());
    const maxOptionIndex = optionKeys.length > 0 ? Math.max(...optionKeys) : -1;

    let startIndex = 0;
    try {
      while (startIndex <= maxOptionIndex) {
        const nextOptionIndex = Math.min(...optionKeys.filter((index) => index >= startIndex));
        // No positionals are declared, so anything before the next option is
        // unparseable and goes straight to extras.
        if (startIndex !== nextOptionIndex) {
          extras.push(...args.slice(startIndex, nextOptionIndex));
          startIndex = nextOptionIndex;
        }
        startIndex = consumeOptional(nextOptionIndex);
      }
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }

    extras.push(...args.slice(startIndex));

    const missing = this.actions
      .filter((action) => action.required && !seenActions.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }
}

