input.new_string:
/**
 * Terminal width, mirroring `shutil.get_terminal_size().columns - 2`:
 * `COLUMNS` wins when it parses to a positive integer, otherwise the real
 * terminal size, otherwise the 80-column fallback (the case that applies
 * whenever output is redirected, i.e. under any test harness).
 */
get formatterWidth() {
  const fromEnv = parseInt(process.env.COLUMNS || '', 10);
  if (Number.isFinite(fromEnv) && fromEnv > 0) return fromEnv - 2;
  const tty = process.stdout && process.stdout.isTTY ? process.stdout.columns : 0;
  return (tty > 0 ? tty : 80) - 2;
}

