/**
 * `consume_optional`. Actions are collected into `actionTuples` and only
 * applied once the loop settles, so an error raised part-way through a
 * concatenated short-option chain applies nothing at all.
 */
const consumeOptional = (startIndex) => {
  let [action, optionString, sep, explicitArg] = optionIndices.get(startIndex);
  const actionTuples = [];
  let stop;

  for (;;) {
    if (action === null) {
      extras.push(args[startIndex]);
      return startIndex + 1;
    }

    if (explicitArg !== null) {
      const argCount = this.matchArgument(action, ['A']);
      const chars = this.prefixChars;

      if (argCount === 0 && !chars.includes(optionString[1]) && explicitArg !== '') {
        // A single-dash flag with something glued to it: try to read the
        // tail as further short options, as in `-hx` -> `-h` then `-x`.
        // An explicit `=` or a dash-prefixed tail is a hard error instead.
        if (sep || chars.includes(explicitArg[0])) {
          throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
        }
        actionTuples.push([action, [], optionString]);
        const char = optionString[0];
        optionString = char + explicitArg[0];
        if (this.optionStringActions.has(optionString)) {
          action = this.optionStringActions.get(optionString);
          explicitArg = explicitArg.slice(1);
          if (explicitArg === '') {
            sep = null;
            explicitArg = null;
          } else if (explicitArg[0] === '=') {
            sep = '=';
            explicitArg = explicitArg.slice(1);
          } else {
            sep = '';
          }
          continue;
        }
        extras.push(char + explicitArg);
        stop = startIndex + 1;
        break;
      }

      if (argCount === 1) {
        stop = startIndex + 1;
        actionTuples.push([action, [explicitArg], optionString]);
        break;
      }

      throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
    }

    const start = startIndex + 1;
    const argCount = this.matchArgument(action, pattern.slice(start));
    stop = start + argCount;
    actionTuples.push([action, args.slice(start, stop)]);
    break;
  }

  for (const [tupleAction, values] of actionTuples) takeAction(tupleAction, values);
  return stop;
